// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/v1/albums/auth/challenges", wrapper.CreateAlbumLoginChallenge)
	router.POST(options.BaseURL+"/v1/albums/auth/apple", wrapper.LoginAlbumWithApple)
	router.POST(options.BaseURL+"/v1/albums/auth/logout", wrapper.LogoutAlbumSession)
	router.GET(options.BaseURL+"/v1/albums/account", wrapper.GetAlbumAccount)
	router.GET(options.BaseURL+"/v1/albums/library/versions", wrapper.ListAlbumAssetVersions)
	router.GET(options.BaseURL+"/v1/albums/library/versions/:versionID", wrapper.GetAlbumAssetVersion)
	router.POST(options.BaseURL+"/v1/albums/library/versions/:versionID/resources/:resourceID/read-grant", wrapper.AuthorizeAlbumOriginalRead)
	router.POST(options.BaseURL+"/v1/albums/library/versions/:versionID/photo-previews/:preset/read-grant", wrapper.AuthorizeAlbumPhotoPreviewRead)
	router.POST(options.BaseURL+"/v1/albums/library/versions/:versionID/video-previews/:preset/read-grant", wrapper.AuthorizeAlbumVideoPreviewRead)
	router.POST(options.BaseURL+"/v1/albums/uploads", wrapper.CreateAlbumUpload)
	router.GET(options.BaseURL+"/v1/albums/uploads/:id", wrapper.GetAlbumUpload)
	router.POST(options.BaseURL+"/v1/albums/uploads/:id/grants", wrapper.AuthorizeAlbumUploadResources)
	router.POST(options.BaseURL+"/v1/albums/uploads/:id/submit", wrapper.SubmitAlbumUpload)
	router.GET(options.BaseURL+"/v1/albums/uploads/:id/resources/:resourceID/multipart", wrapper.GetAlbumMultipart)
	router.POST(options.BaseURL+"/v1/albums/uploads/:id/resources/:resourceID/multipart", wrapper.InitializeAlbumMultipart)
	router.POST(options.BaseURL+"/v1/albums/uploads/:id/resources/:resourceID/multipart/parts/:partNumber/grant", wrapper.AuthorizeAlbumMultipartPart)
	router.POST(options.BaseURL+"/v1/albums/uploads/:id/resources/:resourceID/multipart/complete", wrapper.CompleteAlbumMultipart)
}

